import{bQ as o,aZ as n,aL as r,u as d,G as e,I as i}from"./chunks/framework.C1gZXFVa.js";const _=JSON.parse('{"title":"coinex-account 启动流程","description":"账务服务启动后如何就绪；批处理进程如何开始扫描 pending 流水。","frontmatter":{"title":"coinex-account 启动流程","description":"账务服务启动后如何就绪；批处理进程如何开始扫描 pending 流水。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070504"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070504"}],["meta",{"property":"og:title","content":"coinex-account 启动流程 · TGEX"}],["meta",{"property":"og:description","content":"账务服务启动后如何就绪；批处理进程如何开始扫描 pending 流水。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"coinex-account 启动流程 · TGEX"}],["meta",{"name":"twitter:description","content":"账务服务启动后如何就绪；批处理进程如何开始扫描 pending 流水。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"coinex-account 启动流程\\",\\"description\\":\\"账务服务启动后如何就绪；批处理进程如何开始扫描 pending 流水。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070504\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070504\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070504.md","filePath":"07.现货手册/05.核心交易流程/04.账务初始化链路.md"}'),c={name:"pages/070504.md"};function p(h,t,l,s,b,u){const a=n("Flow");return r(),d("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="coinex-account-启动流程" tabindex="-1">coinex-account 启动流程 <a class="header-anchor" href="#coinex-account-启动流程" aria-label="Permalink to &quot;coinex-account 启动流程&quot;">​</a></h1><div class="doc-lead">账务在线进程启动后不做全站钱包预热；就绪就是接口与消息通道可用。批处理进程则会在启动后立刻开始扫 pending。</div><p>工程：<code>coinex-account</code>。分两个可运行进程理解：</p><table tabindex="0"><thead><tr><th>进程</th><th>角色</th><th>启动后业务准备</th></tr></thead><tbody><tr><td><code>account-provider</code></td><td>在线 Dubbo + MQ 改账</td><td>无全量钱包加载；导出服务、订阅 MQ</td></tr><tr><td><code>account-batch</code></td><td>消化 pending、迁 ES</td><td><code>ApplicationRunner</code> 拉起多组循环任务</td></tr></tbody></table><p>本文写的是<strong>启动后业务行为</strong>，不是运维如何敲启动命令。</p><h2 id="先建立正确预期" tabindex="-1">先建立正确预期 <a class="header-anchor" href="#先建立正确预期" aria-label="Permalink to &quot;先建立正确预期&quot;">​</a></h2><ul><li><strong>不会</strong>在启动时把所有用户余额装进内存。</li><li><strong>不会</strong>像撮合那样按交易对恢复订单簿。</li><li>provider 就绪 = 能响应冻结 / 解冻 / 入账 RPC，并能消费相关 MQ。</li><li>端到端账务闭环通常还需要 <strong>batch</strong> 在跑（pending → 正式流水 / ES）。</li></ul><h2 id="account-provider" tabindex="-1">account-provider <a class="header-anchor" href="#account-provider" aria-label="Permalink to &quot;account-provider&quot;">​</a></h2><h3 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h3>',10)),i(a,{steps:["配置与连接池就绪","导出账务 Dubbo 服务","注册异常 EventBus","订阅资产相关 MQ","心跳探库","按请求懒加载与改账"]}),t[1]||(t[1]=e('<h3 id="_1-容器与基础设施" tabindex="-1">1. 容器与基础设施 <a class="header-anchor" href="#_1-容器与基础设施" aria-label="Permalink to &quot;1. 容器与基础设施&quot;">​</a></h3><p>Apollo 注入数据源、Dubbo、Redis、ES 等。<br> MyBatis Mapper、Jedis / Redisson、ES 客户端在刷新阶段建立连接。<br> Dubbo Consumer <code>check=false</code> 时，下游暂时不在线也不阻断本进程启动。</p><h3 id="_2-导出账务能力" tabindex="-1">2. 导出账务能力 <a class="header-anchor" href="#_2-导出账务能力" aria-label="Permalink to &quot;2. 导出账务能力&quot;">​</a></h3><p>扫描并导出大量账务 Dubbo 服务（用户币币钱包、商户钱包、各类业务账户操作、管理向调账等）。<br> 现货下单冻结、成交结算、撤单解冻，最终都依赖这些接口在注册中心可见。</p><h3 id="_3-eventbus" tabindex="-1">3. EventBus <a class="header-anchor" href="#_3-eventbus" aria-label="Permalink to &quot;3. EventBus&quot;">​</a></h3><p><code>ContextRefreshedEvent</code> 后注册例如：</p><table tabindex="0"><thead><tr><th>监听</th><th>作用</th></tr></thead><tbody><tr><td>账务异常事件</td><td>异步写入异常表</td></tr><tr><td>资产迁移类事件</td><td>特定版本资产迁移执行</td></tr></tbody></table><p>启动时只注册，不扫全站账户。</p><h3 id="_4-rocketmq-消费" tabindex="-1">4. RocketMQ 消费 <a class="header-anchor" href="#_4-rocketmq-消费" aria-label="Permalink to &quot;4. RocketMQ 消费&quot;">​</a></h3><p>启动后订阅多类主题（以代码启用为准），例如：</p><ul><li>余额平衡批量更新</li><li>币币 / 合约 / 期权等提现或手续费结果</li><li>OTC 成交入账、取消解冻</li><li>外部期货划转 / 订单结果</li></ul><p>有积压则启动后立即消费；<strong>改账发生在 <code>onMessage</code>，不在启动预热阶段。</strong></p><h3 id="_5-心跳" tabindex="-1">5. 心跳 <a class="header-anchor" href="#_5-心跳" aria-label="Permalink to &quot;5. 心跳&quot;">​</a></h3><p>默认探活端口上执行轻量查库（如按固定主键查钱包表），用于确认 DB 可读。<br> 不等于「所有 Dubbo 依赖方已上线」。</p><h3 id="_6-applicationready-之后" tabindex="-1">6. ApplicationReady 之后 <a class="header-anchor" href="#_6-applicationready-之后" aria-label="Permalink to &quot;6. ApplicationReady 之后&quot;">​</a></h3><p><code>AwaitingNonWebApplicationListener</code> 阻塞保活。<br> 另有按分钟跑的定时任务（如部分充值单对齐、C2C 超时关单），属于运行期调度，不是一次性 init。</p><h3 id="_7-运行时才出现的「初始化」" tabindex="-1">7. 运行时才出现的「初始化」 <a class="header-anchor" href="#_7-运行时才出现的「初始化」" aria-label="Permalink to &quot;7. 运行时才出现的「初始化」&quot;">​</a></h3><p>代码里大量 <code>init*</code> 出现在<strong>开户 / 首次动某币种钱包</strong>等业务方法中，例如用户某业务账户尚不存在时再创建。<br> 那是请求路径上的惰性建账，不要写成「启动时全量 init 钱包」。</p><p>本地幂等、流水号占用等依赖 Redis <code>TokenManager</code>，也在<strong>请求时</strong>使用。</p><h3 id="provider-就绪含义" tabindex="-1">provider 就绪含义 <a class="header-anchor" href="#provider-就绪含义" aria-label="Permalink to &quot;provider 就绪含义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>含义</th></tr></thead><tbody><tr><td>框架 Ready</td><td>进程保活、配置已加载</td></tr><tr><td>接口 Ready</td><td>账务 Dubbo 已注册</td></tr><tr><td>消息 Ready</td><td>资产相关 Consumer 已订阅</td></tr><tr><td>探活 Ready</td><td>心跳查库成功</td></tr><tr><td>全量资产视图</td><td><strong>不存在</strong>于启动完成时</td></tr></tbody></table><h2 id="account-batch" tabindex="-1">account-batch <a class="header-anchor" href="#account-batch" aria-label="Permalink to &quot;account-batch&quot;">​</a></h2><p>批处理是另一条进程，<strong>有明确的启动后业务循环</strong>。</p><h3 id="applicationrunner-run" tabindex="-1"><code>ApplicationRunner.run()</code> <a class="header-anchor" href="#applicationrunner-run" aria-label="Permalink to &quot;`ApplicationRunner.run()`&quot;">​</a></h3><p>Spring 就绪后启动多组调度线程（延迟约百毫秒～1 秒后开始），典型包括：</p><table tabindex="0"><thead><tr><th>循环</th><th>业务</th></tr></thead><tbody><tr><td>批量执行 pending 账务日志</td><td>消化 <code>pending</code> 类流水</td></tr><tr><td>补偿</td><td>异常 pending 再处理</td></tr><tr><td>迁流水到 ES</td><td>pending / 正式流水检索侧</td></tr><tr><td>迁快照到 ES</td><td>资产快照检索侧</td></tr></tbody></table><p>失败时可能降级为更细粒度的单用户执行。<br> EventBus 上还有批处理异常监听，用于回写 pending 状态。</p><h3 id="batch-就绪含义" tabindex="-1">batch 就绪含义 <a class="header-anchor" href="#batch-就绪含义" aria-label="Permalink to &quot;batch 就绪含义&quot;">​</a></h3><p>Runner 已提交任务，且循环已开始扫库。<br> 它不预加载全站余额，但<strong>持续让 provider 写下的 pending 被消化</strong>。现货成交高峰时，若只起 provider 不起 batch，会出现在线余额已变、检索 / 部分异步链路滞后的现象。</p><h2 id="和交易闭环的关系" tabindex="-1">和交易闭环的关系 <a class="header-anchor" href="#和交易闭环的关系" aria-label="Permalink to &quot;和交易闭环的关系&quot;">​</a></h2><p>贯穿示例中的占用、成交扣减冻结、撤单解冻，都由 account-provider 在请求或 MQ 路径上完成。<br> 委托入口见<a href="/pages/070502">委托初始化链路</a>；撮合见<a href="/pages/070503">撮合初始化链路</a>；资金动作语义见<a href="/pages/070501">业务流程</a>。</p>',31))])}const m=o(c,[["render",p]]);export{_ as __pageData,m as default};
